<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';require_permission('inventory.view');
if($_SERVER['REQUEST_METHOD']==='POST'){
 require_permission('inventory.manage');verify_csrf();$action=(string)($_POST['action']??'');
 if($action==='create'){$name=trim((string)($_POST['item_name']??''));$category=trim((string)($_POST['category']??''));$unit=trim((string)($_POST['unit']??''));$qty=filter_var($_POST['quantity']??0,FILTER_VALIDATE_INT);$reorder=filter_var($_POST['reorder_level']??0,FILTER_VALIDATE_INT);if($name===''||strlen($name)>160||$category===''||strlen($category)>100||$unit===''||strlen($unit)>40||$qty===false||$qty<0||$reorder===false||$reorder<0){set_flash('danger','Complete the stock item details with valid quantities.');redirect('/hospital%20management/inventory/index.php');}$q=$pdo->prepare('INSERT INTO inventory(item_name,category,quantity,reorder_level,unit) VALUES(:name,:category,:quantity,:reorder,:unit)');$q->execute(['name'=>$name,'category'=>$category,'quantity'=>$qty,'reorder'=>$reorder,'unit'=>$unit]);$id=(string)$pdo->lastInsertId();record_audit('create','inventory_item',$id,'Inventory item created');notify_staff('inventory_adjusted','inventory_item',$id,current_user()['full_name'].' added a new stock item: '.$name.'.');set_flash('success','Stock item added.');}
 elseif($action==='adjust'){$id=filter_var($_POST['item_id']??'',FILTER_VALIDATE_INT);$delta=filter_var($_POST['quantity_delta']??'',FILTER_VALIDATE_INT);$reason=trim((string)($_POST['reason']??''));if(!$id||$delta===false||$delta===0||abs($delta)>1000000||$reason===''||strlen($reason)>255){set_flash('danger','Enter a stock change between 1 and 1,000,000 units and a reason.');redirect('/hospital%20management/inventory/index.php');}$q=$pdo->prepare('UPDATE inventory SET quantity=quantity+:delta WHERE id=:id AND quantity+:delta_check>=0');$q->execute(['delta'=>$delta,'id'=>$id,'delta_check'=>$delta]);if($q->rowCount()){record_audit('adjust','inventory_item',(string)$id,'Stock adjusted by '.$delta.'; '.$reason);notify_staff('inventory_adjusted','inventory_item',(string)$id,current_user()['full_name'].' adjusted stock by '.$delta.' units: '.$reason.'.');set_flash('success','Stock updated.');}else set_flash('danger','The item was not found or the adjustment would make stock negative.');}
 else{http_response_code(400);exit('Unknown inventory action.');}redirect('/hospital%20management/inventory/index.php');
}
$items=$pdo->query('SELECT id,item_name,category,quantity,reorder_level,unit,updated_at FROM inventory ORDER BY category,item_name')->fetchAll();$pageTitle='Inventory and supplies';require __DIR__.'/../includes/header.php';?>
<div class="page-heading"><div><h2>Inventory and supplies</h2><p>Track hospital supplies and equipment stock, record receipts, and flag reorder levels.</p></div></div>
<?php if(has_permission('inventory.manage')):?><section class="content-card form-card mt-0"><div class="card-heading"><h3>Add stock item</h3></div><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="create"><div class="col-md-3"><label class="form-label">Item</label><input class="form-control" name="item_name" maxlength="160" required></div><div class="col-md-2"><label class="form-label">Category</label><input class="form-control" name="category" maxlength="100" required></div><div class="col-md-2"><label class="form-label">Unit</label><input class="form-control" name="unit" maxlength="40" placeholder="boxes, units" required></div><div class="col-md-2"><label class="form-label">Initial stock</label><input class="form-control" type="number" name="quantity" min="0" value="0" required></div><div class="col-md-2"><label class="form-label">Reorder at</label><input class="form-control" type="number" name="reorder_level" min="0" value="0" required></div><div class="col-md-1 d-flex align-items-end"><button class="btn btn-primary">Add</button></div></form></section><?php endif;?>
<section class="content-card"><div class="card-heading"><h3>Stock register <span class="subtle">(<?=count($items)?> items)</span></h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Item</th><th>Category</th><th>Quantity</th><th>Reorder level</th><th>Last updated</th><?php if(has_permission('inventory.manage')):?><th>Record stock change</th><?php endif;?></tr></thead><tbody><?php if(!$items):?><tr><td class="empty-state" colspan="6">No stock items recorded.</td></tr><?php else:foreach($items as $item):?><tr><td><?=e($item['item_name'])?></td><td><?=e($item['category'])?></td><td><strong class="<?= (int)$item['quantity'] <= (int)$item['reorder_level']?'text-danger':'' ?>"><?= (int)$item['quantity']?> <?=e($item['unit'])?></strong><?php if((int)$item['quantity'] <= (int)$item['reorder_level']):?> <span class="badge-soft">Reorder</span><?php endif;?></td><td><?= (int)$item['reorder_level']?> <?=e($item['unit'])?></td><td><?=e(date('M j, Y g:i a',strtotime($item['updated_at'])))?></td><?php if(has_permission('inventory.manage')):?><td><form method="post" class="d-flex gap-1"><?=csrf_field()?><input type="hidden" name="action" value="adjust"><input type="hidden" name="item_id" value="<?=(int)$item['id']?>"><input class="form-control form-control-sm" type="number" name="quantity_delta" placeholder="+/- units" required><input class="form-control form-control-sm" name="reason" maxlength="255" placeholder="Receipt, use, correction" required><button class="btn btn-sm btn-outline-secondary">Save</button></form></td><?php endif;?></tr><?php endforeach;endif;?></tbody></table></div></section>
<?php require __DIR__.'/../includes/footer.php';?>
